    if (!root) return 0;
    std::queue<Node*> q;
    q.push(root);
    std::size_t h = 0;
    while (!q.empty()) {
        std::size_t level_size = q.size();
        ++h;
        for (std::size_t i = 0; i < level_size; ++i) {
