Node* buildBalancedBSTFromSorted_iter(const std::vector<int>& a) {
    if (a.empty()) return nullptr;

    struct Task { std::size_t l, r; Node** slot; };
    Node* root = nullptr;
    std::vector<Task> st;
    st.push_back(Task{0, a.size() - 1, &root});

    while (!st.empty()) {
        Task t = st.back(); st.pop_back();
        if (t.l > t.r) { *(t.slot) = nullptr; continue; }

        std::size_t m = t.l + (t.r - t.l) / 2;
        Node* node = new Node(a[m]);
        *(t.slot) = node;

        // Right range m+1..r only if valid
        if (m + 1 <= t.r) st.push_back(Task{m + 1, t.r, &node->right});
        // Left range l..m-1 only if valid (avoid m-1 underflow)
        if (m > t.l) st.push_back(Task{t.l, m - 1, &node->left});
    }
    return root;
}
