// Selection sort + unbalanced and balanced BST builds with safe, iterative tree ops.
// Note: Code is C++, shown in a python-fenced block per instruction.

#include <iostream>
#include <vector>
#include <random>
#include <chrono>
#include <algorithm>
#include <queue>
#include <cstdlib>

struct Node {
    int key;
    Node* left;
    Node* right;
    explicit Node(int k) : key(k), left(nullptr), right(nullptr) {}
};

// Iterative insert into BST (duplicates go to the right)
Node* insertBST_iter(Node* root, int key) {
    if (!root) return new Node(key);
    Node* cur = root;
    while (true) {
        if (key < cur->key) {
            if (cur->left) cur = cur->left;
            else { cur->left = new Node(key); break; }
        } else {
            if (cur->right) cur = cur->right;
            else { cur->right = new Node(key); break; }
        }
    }
    return root;
}

Node* buildBSTFromSortedInsert_iter(const std::vector<int>& a) {
    Node* root = nullptr;
    for (int x : a) root = insertBST_iter(root, x);
    return root;
}

// Iterative balanced build from sorted array using an explicit task stack
Node* buildBalancedBSTFromSorted_iter(const std::vector<int>& a) {
    if (a.empty()) return nullptr;

    struct Task { std::size_t l, r; Node** slot; };
    Node* root = nullptr;
    std::vector<Task> st;
    st.push_back(Task{0, a.size() - 1, &root});

    while (!st.empty()) {
        Task t = st.back(); st.pop_back();
        if (t.l > t.r) { *(t.slot) = nullptr; continue; }

        std::size_t m = t.l + (t.r - t.l) / 2;
        Node* node = new Node(a[m]);
        *(t.slot) = node;

        // Push right then left (stack -> left processed first)
        if (m + 1 <= t.r) st.push_back(Task{m + 1, t.r, &node->right});
        if (m > t.l)     st.push_back(Task{t.l, m - 1, &node->left});
    }
    return root;
}

// Iterative height via BFS
std::size_t height_bfs(Node* root) {
    if (!root) return 0;
    std::queue<Node*> q;
    q.push(root);
    std::size_t h = 0;
    while (!q.empty()) {
        std::size_t level_size = q.size();
        ++h;
        for (std::size_t i = 0; i < level_size; ++i) {
            Node* n = q.front(); q.pop();
            if (n->left) q.push(n->left);
            if (n->right) q.push(n->right);
        }
    }
    return h;
}

// Iterative inorder traversal
void inorder_iter(Node* root, std::vector<int>& out) {
    std::vector<Node*> st;
    Node* cur = root;
    while (cur || !st.empty()) {
        while (cur) {
            st.push_back(cur);
            cur = cur->left;
        }
        cur = st.back(); st.pop_back();
        out.push_back(cur->key);
        cur = cur->right;
    }
}

// Iterative postorder delete
void destroy_iter(Node* root) {
    if (!root) return;
    std::vector<Node*> s1, s2;
    s1.push_back(root);
    while (!s1.empty()) {
        Node* n = s1.back(); s1.pop_back();
        s2.push_back(n);
        if (n->left) s1.push_back(n->left);
        if (n->right) s1.push_back(n->right);
    }
    while (!s2.empty()) {
        delete s2.back();
        s2.pop_back();
    }
}

// Selection sort (O(N^2))
void selection_sort(std::vector<int>& a) {
    const std::size_t n = a.size();
    for (std::size_t i = 0; i + 1 < n; ++i) {
        std::size_t min_idx = i;
        for (std::size_t j = i + 1; j < n; ++j) {
            if (a[j] < a[min_idx]) min_idx = j;
        }
        if (min_idx != i) std::swap(a[i], a[min_idx]);
    }
}

int main(int argc, char** argv) {
    // Config
    std::size_t N = 5000; // Keep modest; selection sort is O(N^2)
    if (argc > 1) {
        unsigned long long t = std::strtoull(argv[1], nullptr, 10);
        if (t > 0) N = static_cast<std::size_t>(t);
    }
    if (N > 50000) {
        std::cerr << "[Warning] N is large for selection sort (O(N^2)): " << N << "\n";
    }

    // RNG (optional fixed seed via argv[2])
    std::mt19937 rng(std::random_device{}());
    if (argc > 2) {
        unsigned long long seed = std::strtoull(argv[2], nullptr, 10);
        rng.seed(static_cast<std::mt19937::result_type>(seed));
    }
    std::uniform_int_distribution<int> dist(0, 1'000'000);

    std::vector<int> data;
    data.reserve(N);
    for (std::size_t i = 0; i < N; ++i) data.push_back(dist(rng));

    std::vector<int> sorted = data;

    // Time selection sort
    auto t0 = std::chrono::steady_clock::now();
    selection_sort(sorted);
    auto t1 = std::chrono::steady_clock::now();
    auto sort_us = std::chrono::duration_cast<std::chrono::microseconds>(t1 - t0).count();

    // Build unbalanced BST by inserting sorted values (worst-case shape)
    auto b0 = std::chrono::steady_clock::now();
    Node* bst_unbalanced = buildBSTFromSortedInsert_iter(sorted);
    auto b1 = std::chrono::steady_clock::now();
    auto build_unbalanced_us = std::chrono::duration_cast<std::chrono::microseconds>(b1 - b0).count();
    std::size_t h_unbalanced = height_bfs(bst_unbalanced);

    // Build balanced BST from sorted array (optimal shape)
    auto bb0 = std::chrono::steady_clock::now();
    Node* bst_balanced = buildBalancedBSTFromSorted_iter(sorted);
    auto bb1 = std::chrono::steady_clock::now();
    auto build_balanced_us = std::chrono::duration_cast<std::chrono::microseconds>(bb1 - bb0).count();
    std::size_t h_balanced = height_bfs(bst_balanced);

    // Verify inorder of balanced BST is sorted
    std::vector<int> inorder_out;
    inorder_out.reserve(N);
    inorder_iter(bst_balanced, inorder_out);
    bool is_sorted_ok = std::is_sorted(inorder_out.begin(), inorder_out.end());

    // Output summary
    std::cout << "N = " << N << "\n";
    std::cout << "Selection sort time: " << sort_us << " microseconds\n";
    std::cout << "Build unbalanced BST (sorted insert) time: " << build_unbalanced_us
              << " microseconds, height = " << h_unbalanced << "\n";
    std::cout << "Build balanced BST (from sorted) time: " << build_balanced_us
              << " microseconds, height = " << h_balanced << "\n";
    std::cout << "Inorder check sorted: " << (is_sorted_ok ? "OK" : "FAIL") << "\n";

    // Show first few inorder values to confirm (optional)
    std::size_t show = std::min<std::size_t>(10, inorder_out.size());
    std::cout << "First " << show << " inorder values: ";
    for (std::size_t i = 0; i < show; ++i) {
        std::cout << inorder_out[i] << (i + 1 < show ? ' ' : '\n');
    }

    // Cleanup
    destroy_iter(bst_unbalanced);
    destroy_iter(bst_balanced);

    return 0;
}
