import { ResultType, StepResponse } from '@txp-core/runtime';
import { put } from 'redux-saga/effects';
import {
  PaymentChargesTableAction,
  paymentTableSelectors
} from '@txp-core/payment-transactions-table';
import { select } from '@txp-core/basic-utils';
import type { CreditChargesPaymentTypes } from '@txp-core/payment-transactions-table/dist/paymentTableStateTypes';

// Configuration
const DECIMALS = 2;

// Consolidated, robust parsing and formatting utilities
function parseNumber(value: unknown, fallback = 0): number {
  if (value == null) return fallback;
  if (typeof value === 'number') return Number.isFinite(value) ? value : fallback;
  if (typeof value === 'bigint') {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  }
  if (typeof value === 'boolean') return fallback;

  // Attempt normalization from string or other object types
  try {
    let s = String(value).trim();
    if (s === '') return fallback;

    // Normalize Unicode minus variants
    s = s.replace(/[−–—]/g, '-');

    // Parentheses negatives: "(123.45)" -> "-123.45"
    const parenNeg = /^\(\s*.*\s*\)$/.test(s);
    if (parenNeg) s = s.slice(1, -1).trim();

    // Remove currency symbols and letters; keep digits, separators, signs, and spaces
    s = s.replace(/[^\d.,+\-\s\u00A0]/g, '');
    // Remove spaces (incl. NBSP)
    s = s.replace(/\u00A0/g, '').replace(/\s+/g, '');

    // Determine decimal vs thousand separators
    if (s.includes('.') && s.includes(',')) {
      const lastDot = s.lastIndexOf('.');
      const lastComma = s.lastIndexOf(',');
      const decSep = lastDot > lastComma ? '.' : ',';
      const thouSep = decSep === '.' ? ',' : '.';
      s = s.split(thouSep).join('');
      s = s.replace(decSep, '.');
    } else if (s.includes(',') && !s.includes('.')) {
      const last = s.lastIndexOf(',');
      const digitsAfter = s.length - last - 1;
      if (digitsAfter >= 1 && digitsAfter <= 2) {
        s = s.replace(',', '.');
      } else {
        s = s.split(',').join('');
      }
    } else if ((s.match(/\./g) || []).length > 1) {
      const last = s.lastIndexOf('.');
      s = s.slice(0, last).replace(/\./g, '') + '.' + s.slice(last + 1);
    }

    // Preserve a single leading sign; drop stray signs
    const signMatch = s.match(/^[+\-]+/);
    let sign = '';
    if (signMatch) {
      sign = signMatch[0].includes('-') ? '-' : '+';
      s = s.slice(signMatch[0].length);
    }
    s = s.replace(/[^\d.]/g, '');

    let normalized = (sign || '') + s;
    if (parenNeg && !normalized.startsWith('-')) normalized = '-' + normalized;

    if (!/^[+\-]?\d*\.?\d+$/.test(normalized)) return fallback;

    const n = Number(normalized);
    return Number.isFinite(n) ? n : fallback;
  } catch {
    return fallback;
  }
}

function normalizeAmount(
  value: unknown,
  options?: { decimals?: number; nonNegative?: boolean }
): number {
  const decimals = options?.decimals ?? DECIMALS;
  const nonNegative = options?.nonNegative ?? false;
  let n = parseNumber(value, 0);
  if (nonNegative && n < 0) n = 0;
  const factor = 10 ** decimals;
  n = Math.round((n + Number.EPSILON) * factor) / factor;
  return n;
}

function toAmountString(n: number, decimals = DECIMALS): string {
  const fixed = n.toFixed(decimals);
  const trimmed = fixed.replace(/\.?0+$/, '');
  return trimmed === '' ? '0' : trimmed;
}

// Saga
export function* outstandingTransactionsHandler(): Generator<any, StepResponse, any> {
  try {
    const creditTableLines: CreditChargesPaymentTypes[] =
      (yield* select(paymentTableSelectors.getCredits)) ?? [];

    const totalOfChargesTableRaw: unknown =
      yield* select(paymentTableSelectors.getTotalOfChargesTable);

    let remaining = normalizeAmount(totalOfChargesTableRaw, {
      nonNegative: true,
      decimals: DECIMALS
    });

    if (!Array.isArray(creditTableLines) || creditTableLines.length === 0) {
      return { result: ResultType.SUCCESS };
    }

    let didChange = false;

    const updatedCreditTable: CreditChargesPaymentTypes[] = creditTableLines.map((credit) => {
      const next: CreditChargesPaymentTypes = { ...credit }; // immutability

      // Checked means non-empty string (including '0')
      const isChecked = String(credit?.linkedPaymentAmount ?? '') !== '';
      if (!isChecked) return next;

      const openBalance = normalizeAmount(credit?.openBalance, {
        nonNegative: true,
        decimals: DECIMALS
      });

      if (remaining <= 0) {
        if (next.linkedPaymentAmount !== '') {
          next.linkedPaymentAmount = '';
          didChange = true;
        }
        return next;
      }

      const allocation = Math.min(openBalance, remaining);
      const formatted = toAmountString(allocation, DECIMALS);

      if (next.linkedPaymentAmount !== formatted) {
        next.linkedPaymentAmount = formatted;
        didChange = true;
      }

      remaining = normalizeAmount(remaining - allocation, {
        nonNegative: true,
        decimals: DECIMALS
      });

      return next;
    });

    if (didChange) {
      yield put(PaymentChargesTableAction.fullCreditsTableUpdate(updatedCreditTable));
    }

    return { result: ResultType.SUCCESS };
  } catch (err) {
    return {
      result: ResultType.FAILURE,
      message: 'Unable to allocate outstanding transactions'
    } as StepResponse;
  }
}

import { ResultType, StepResponse } from '@txp-core/runtime';
import { put } from 'redux-saga/effects';
import {
  PaymentChargesTableAction,
  paymentTableSelectors
} from '@txp-core/payment-transactions-table';
import { select } from '@txp-core/basic-utils';
import type { CreditChargesPaymentTypes } from '@txp-core/payment-transactions-table/dist/paymentTableStateTypes';

// Configuration
const DECIMALS = 2;

// Optimized numeric parsing for performance and simplified handling of numeric strings
const parseAmount = (value: unknown, opts: { nonNegative?: boolean } = {}): number => {
  const { nonNegative = false } = opts;

  // Fast paths
  if (value == null || typeof value === 'boolean') return 0;
  if (typeof value === 'number') {
    const n = Number.isFinite(value) ? value : 0;
    return nonNegative && n < 0 ? 0 : n;
  }

  // Convert to string safely
  let s: string;
  try {
    s = String(value);
  } catch {
    return 0;
  }

  s = s.trim();
  if (!s) return 0;

  // Normalize common unicode minus signs to ASCII '-'
  s = s.replace(/[\u2212\u2013\u2014]/g, '-');

  // Parentheses negative e.g. (123.45)
  const parenNeg = s.startsWith('(') && s.endsWith(')');
  if (parenNeg) s = s.slice(1, -1).trim();

  // Remove spaces (incl. NBSP)
  s = s.replace(/\u00A0/g, '').replace(/\s+/g, '');

  // Filter allowed characters in a single pass: digits, '.', ',', "'", '+', '-'
  let filtered = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    const isDigit = c >= '0' && c <= '9';
    if (isDigit || c === '.' || c === ',' || c === '\'' || c === '+' || c === '-') {
      filtered += c;
    }
  }
  if (!filtered) return 0;

  // Remove apostrophes used as thousands separators
  if (filtered.indexOf("'") !== -1) filtered = filtered.split("'").join('');

  let hasDot = filtered.indexOf('.') !== -1;
  let hasComma = filtered.indexOf(',') !== -1;

  if (hasDot && hasComma) {
    const lastDot = filtered.lastIndexOf('.');
    const lastComma = filtered.lastIndexOf(',');
    const decimalIsDot = lastDot > lastComma;
    if (decimalIsDot) {
      filtered = filtered.replace(/,/g, '');
      const dotCount = (filtered.match(/\./g) || []).length;
      if (dotCount > 1) {
        const last = filtered.lastIndexOf('.');
        filtered = filtered.slice(0, last).replace(/\./g, '') + '.' + filtered.slice(last + 1);
      }
    } else {
      filtered = filtered.replace(/\./g, '');
      const commaCount = (filtered.match(/,/g) || []).length;
      if (commaCount > 1) {
        const last = filtered.lastIndexOf(',');
        filtered = filtered.slice(0, last).replace(/,/g, '') + '.' + filtered.slice(last + 1);
      } else {
        filtered = filtered.replace(',', '.');
      }
    }
  } else if (hasComma) {
    // Heuristic: treat last comma as decimal if 1–2 digits follow; otherwise thousands
    const last = filtered.lastIndexOf(',');
    let digitsAfter = 0;
    for (let i = last + 1; i < filtered.length && digitsAfter <= 2; i++) {
      const c = filtered[i];
      if (c >= '0' && c <= '9') digitsAfter++;
      else break;
    }
    if (digitsAfter >= 1 && digitsAfter <= 2) {
      const commaCount = (filtered.match(/,/g) || []).length;
      if (commaCount > 1) {
        const last = filtered.lastIndexOf(',');
        filtered = filtered.slice(0, last).replace(/,/g, '') + '.' + filtered.slice(last + 1);
      } else {
        filtered = filtered.replace(',', '.');
      }
    } else {
      filtered = filtered.replace(/,/g, '');
    }
  } else if (hasDot) {
    // Keep last dot as decimal, remove others
    const dotCount = (filtered.match(/\./g) || []).length;
    if (dotCount > 1) {
      const last = filtered.lastIndexOf('.');
      filtered = filtered.slice(0, last).replace(/\./g, '') + '.' + filtered.slice(last + 1);
    }
  }

  // Keep only a single leading sign
  let sign = '';
  if (filtered[0] === '-' || filtered[0] === '+') {
    sign = filtered[0];
    filtered = filtered.slice(1);
  }
  filtered = filtered.replace(/[+\-]/g, '');

  // Ensure at least one digit remains
  if (!/[0-9]/.test(filtered)) return 0;

  // Edge cases
  if (filtered[0] === '.') filtered = '0' + filtered;
  if (filtered[filtered.length - 1] === '.') filtered += '0';

  const normalized = (parenNeg || sign === '-') ? '-' + filtered : filtered;
  const n = Number(normalized);
  let out = Number.isFinite(n) ? n : 0;
  if (nonNegative && out < 0) out = 0;
  return out;
};

const roundTo = (n: number, decimals = DECIMALS): number => {
