// ---------- Encapsulated Value Object with Operator Overloading ----------
class Dimension {
private:
    double width_{0}, height_{0}, depth_{0};

public:
    Dimension() = default;
    Dimension(double w, double h, double d) : width_(w), height_(h), depth_(d) {}

    double width() const { return width_; }
    double height() const { return height_; }
    double depth() const { return depth_; }

    double volume() const { return width_ * height_ * depth_; }

    // Operator overloading
    Dimension operator+(const Dimension &other) const {
        return {width_ + other.width_, height_ + other.height_, depth_ + other.depth_};
    }
    Dimension operator*(double s) const { return {width_ * s, height_ * s, depth_ * s}; }
    friend Dimension operator*(double s, const Dimension &d) { return d * s; }

    friend std::ostream &operator<<(std::ostream &os, const Dimension &d) {
        os << d.width_ << "x" << d.height_ << "x" << d.depth_ << " (vol=" << d.volume() << ")";
        return os;
    }
};

// ---------- Base Abstract Class (Encapsulation + Polymorphism) ----------
class Exhibit {
private:
    std::string name_;
    int year_{};
    std::vector<int> ratings_;

protected:
    Exhibit(std::string name, int year) : name_(std::move(name)), year_(year) {}

public:
    virtual ~Exhibit() = default;

    const std::string &getName() const { return name_; }
    int getYear() const { return year_; }

    // Method overloading for ratings
    void addRating(int r) {
        if (r < 1 || r > 5) throw std::out_of_range("Rating must be 1..5");
        ratings_.push_back(r);
    }
    void addRating(const std::vector<int> &rs) {
        for (int r : rs) addRating(r);
    }
    void addRating(std::initializer_list<int> rs) {
        for (int r : rs) addRating(r);
    }

    const std::vector<int> &ratings() const { return ratings_; }

    std::optional<double> averageRating() const {
        if (ratings_.empty()) return std::nullopt;
        double sum = std::accumulate(ratings_.begin(), ratings_.end(), 0.0);
        return sum / ratings_.size();
    }

    // Polymorphic interface
    virtual void display() const = 0;
    virtual std::string type() const = 0;

    // Operator overloading for ordering and equality
    bool operator<(const Exhibit &other) const {
        if (name_ != other.name_) return name_ < other.name_;
        return year_ < other.year_;
    }
    bool operator==(const Exhibit &other) const {
        return name_ == other.name_ && year_ == other.year_ && type() == other.type();
    }

    friend std::ostream &operator<<(std::ostream &os, const Exhibit &e) {
        os << "[" << e.type() << "] " << e.getName() << " (" << e.getYear() << ")";
        if (auto avg = e.averageRating()) os << " avg=" << std::fixed << std::setprecision(2) << *avg;
        return os;
    }
};

// ---------- Derived Classes (Inheritance + Polymorphism) ----------
class Painting : public Exhibit {
private:
    std::string artist_;
    std::string technique_;

public:
    Painting(const std::string &name, int year, const std::string &artist, const std::string &technique = "Oil")
        : Exhibit(name, year), artist_(artist), technique_(technique) {}

    const std::string &getArtist() const { return artist_; }
    const std::string &getTechnique() const { return technique_; }

    void display() const override {
        std::cout << "Displaying painting: " << getName() << " by " << artist_ << " (" << technique_ << ", "
                  << getYear() << ")\n";
    }
    std::string type() const override { return "Painting"; }
};

class Sculpture : public Exhibit {
private:
    std::string material_;
    Dimension size_;

public:
    Sculpture(const std::string &name, int year, const std::string &material, const Dimension &size)
        : Exhibit(name, year), material_(material), size_(size) {}

    const std::string &getMaterial() const { return material_; }
    const Dimension &getSize() const { return size_; }

    void display() const override {
        std::cout << "Displaying sculpture: " << getName() << " made of " << material_ << " size " << size_
                  << " (" << getYear() << ")\n";
    }
    std::string type() const override { return "Sculpture"; }
};

class Photograph : public Exhibit {
private:
    std::string photographer_;
    std::string medium_;

public:
    Photograph(const std::string &name, int year, const std::string &photographer, const std::string &medium = "Film")
        : Exhibit(name, year), photographer_(photographer), medium_(medium) {}

    const std::string &getPhotographer() const { return photographer_; }
    const std::string &getMedium() const { return medium_; }

    void display() const override {
        std::cout << "Displaying photograph: " << getName() << " by " << photographer_ << " (" << medium_ << ", "
                  << getYear() << ")\n";
    }
    std::string type() const override { return "Photograph"; }
};

class Installation : public Exhibit {
private:
    std::vector<std::string> components_;
    double area_m2_{};

public:
    Installation(const std::string &name, int year, std::vector<std::string> components, double area_m2)
        : Exhibit(name, year), components_(std::move(components)), area_m2_(area_m2) {}

    const std::vector<std::string> &components() const { return components_; }
    double area() const { return area_m2_; }

    void display() const override {
        std::string comp;
        for (size_t i = 0; i < components_.size() && i < 3; ++i) {
            if (i) comp += ", ";
            comp += components_[i];
        }
        if (components_.size() > 3) comp += ", ...";
        std::cout << "Displaying installation: " << getName() << " (" << getYear() << ") components: " << comp
                  << ", area=" << std::fixed << std::setprecision(1) << area_m2_ << " m^2\n";
    }
    std::string type() const override { return "Installation"; }
};

// ---------- Templates (Repository and Generic Algorithms) ----------

template <typename T>
class Repository {
private:
    std::vector<std::shared_ptr<T>> items_;

public:
    void add(std::shared_ptr<T> item) { items_.push_back(std::move(item)); }

    template <typename Derived, typename... Args>
    std::shared_ptr<Derived> emplace(Args &&...args) {
        static_assert(std::is_base_of<T, Derived>::value || std::is_same<T, Derived>::value,
                      "Derived must be T or derived from T");
        auto ptr = std::make_shared<Derived>(std::forward<Args>(args)...);
        items_.push_back(ptr);
        return ptr;
    }

    const std::vector<std::shared_ptr<T>> &items() const { return items_; }

    template <typename Pred>
    std::vector<std::shared_ptr<T>> where(Pred p) const {
        std::vector<std::shared_ptr<T>> out;
        std::copy_if(items_.begin(), items_.end(), std::back_inserter(out), [&](const auto &sp) { return p(*sp); });
        return out;
    }
};

template <typename It, typename T = typename std::iterator_traits<It>::value_type>
std::optional<double> average(It first, It last) {
    if (first == last) return std::nullopt;
    double sum = std::accumulate(first, last, 0.0);
    auto n = std::distance(first, last);
    return n ? std::optional<double>(sum / static_cast<double>(n)) : std::nullopt;
}

// ---------- Data Analysis / Processing ----------
class Analyzer {
public:
    struct TypeStats {
        std::size_t count{0};
        std::size_t ratingCount{0};
        double ratingSum{0.0};
        double avg() const { return ratingCount ? ratingSum / static_cast<double>(ratingCount) : 0.0; }
    };

    std::map<std::string, TypeStats> statsByType(const std::vector<std::shared_ptr<Exhibit>> &items) const {
        std::map<std::string, TypeStats> stats;
        for (const auto &e : items) {
            auto &s = stats[e->type()];
            ++s.count;
            for (int r : e->ratings()) {
                ++s.ratingCount;
                s.ratingSum += r;
            }
        }
        return stats;
    }

    std::shared_ptr<Exhibit> topRated(const std::vector<std::shared_ptr<Exhibit>> &items) const {
        if (items.empty()) return nullptr;
        return *std::max_element(items.begin(), items.end(), [](const auto &a, const auto &b) {
            return a->averageRating().value_or(0.0) < b->averageRating().value_or(0.0);
        });
    }
};

// ---------- Aggregator Class Using the Repository ----------
class Museum {
private:
    Repository<Exhibit> repo_;

public:
    Repository<Exhibit> &repo() { return repo_; }
    const Repository<Exhibit> &repo() const { return repo_; }

    void showAll() const {
        for (const auto &e : repo_.items()) {
            e->display();
        }
    }
};

int main() {
    try {
        Museum museum;
        auto &repo = museum.repo();

        // Build sample collection (STL, templates, encapsulation, inheritance, polymorphism)
        auto p1 = repo.emplace<Painting>("The Starry Night", 1889, "Vincent van Gogh", "Oil");
        auto s1 = repo.emplace<Sculpture>("David", 1504, "Marble", Dimension(2.0, 5.17, 1.0));
        auto p2 = repo.emplace<Painting>("The Persistence of Memory", 1931, "Salvador Dali", "Oil");
        auto ph1 = repo.emplace<Photograph>("Moonrise, Hernandez", 1941, "Ansel Adams", "Film");
        auto inst = repo.emplace<Installation>("The Weather Project", 2003,
                                              std::vector<std::string>{"Light", "Mirrors", "Mist", "Steel"}, 300.0);

        // Method overloading demonstration
        p1->addRating({5, 5, 4});
        s1->addRating(5);
        p2->addRating(std::vector<int>{4, 4, 5});
        ph1->addRating({5, 4});
        inst->addRating(3);

        // Operator overloading demonstration
        Dimension dA(1.0, 2.0, 3.0), dB(0.5, 0.5, 0.5);
        Dimension dC = dA + dB * 2.0;
        std::cout << "Combined dimension: " << dC << "\n\n";

        // Original functionality: display all exhibits
        museum.showAll();
        std::cout << "\n--- Summary (polymorphic toString via operator<<) ---\n";
        for (const auto &e : repo.items()) {
            std::cout << *e << "\n";
        }

        // Data processing with templates and STL algorithms
        std::vector<int> years;
        years.reserve(repo.items().size());
        std::transform(repo.items().begin(), repo.items().end(), std::back_inserter(years),
                       [](const std::shared_ptr<Exhibit> &e) { return e->getYear(); });
        if (auto avgYear = average(years.begin(), years.end())) {
            std::cout << "\nAverage year across exhibits: " << std::fixed << std::setprecision(1) << *avgYear << "\n";
        }

        Analyzer analyzer;
        auto byType = analyzer.statsByType(repo.items());
        std::cout << "\nType statistics:\n";
        for (const auto &kv : byType) {
            std::cout << "  " << kv.first << ": count=" << kv.second.count
                      << ", avg-rating=" << std::fixed << std::setprecision(2) << kv.second.avg() << "\n";
        }
        if (auto best = analyzer.topRated(repo.items())) {
            std::cout << "\nTop rated: " << (*best ? (*best)->type() : std::string("")) << " -> " << **best << "\n";
        }

        // Repository::where (templates + STL) to filter recent exhibits
        auto recent = repo.where([](const Exhibit &e) { return e.getYear() >= 1900; });
        std::cout << "\nRecent exhibits (>=1900):\n";
        for (const auto &e : recent) {
            std::cout << "  - " << *e << "\n";
        }

    } catch (const std::exception &ex) {
        std::cerr << "Error: " << ex.what() << "\n";
        return 1;
    }
    return 0;
}

