        firstName: firstName,
        lastName: lastName,
        weight: weight,
        height: height,
        bodyType: bodyType,
        photoUrl: photoUrl,
      );

      if (!mounted) return;
      Navigator.pushNamedAndRemoveUntil(context, ProfilePage.routeName, (_) => false);
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to save: $e')),
